begin;
create extension if not exists pgcrypto;
create schema if not exists private;
revoke all on schema private from public,anon,authenticated;
create table public.profiles(id uuid primary key references auth.users on delete cascade,email text not null,name text not null default '',phone text not null default '',role text not null default 'customer' check(role in ('customer','owner','admin','order_manager','content_manager')),locale text not null default 'en' check(locale in('ar','he','en')),email_updates boolean not null default true,whatsapp_updates boolean not null default false,marketing_consent boolean not null default false,created_at timestamptz not null default now());
create function private.new_profile() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.profiles(id,email,name) values(new.id,coalesce(new.email,''),coalesce(new.raw_user_meta_data->>'name',''));return new;end$$;
create trigger new_profile after insert on auth.users for each row execute function private.new_profile();
create table public.categories(id text primary key,slug text unique not null,name jsonb not null,description jsonb not null,image text not null default '',position integer not null default 0,active boolean not null default true);
create table public.collections(like public.categories including all);
create table public.products(id text primary key,sku text not null unique,slug text not null unique,status text not null default 'draft' check(status in('draft','published','archived')),category_id text references public.categories(id),base_price integer check(base_price>=0),compare_at_price integer check(compare_at_price>=0),featured boolean not null default false,bestseller boolean not null default false,new_arrival boolean not null default false,publish_at timestamptz,made_to_order boolean not null default true,lead_min integer check(lead_min>=0),lead_max integer check(lead_max>=lead_min),customization boolean not null default false,shipping_countries text[] not null default '{IL}',tags text[] not null default '{}',gem jsonb not null default '{}',metal jsonb not null default '{}',measurements jsonb not null default '{}',is_demo boolean not null default false check(is_demo=false),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),check(status<>'published' or base_price is not null));
create table public.product_translations(product_id text references public.products on delete cascade,locale text check(locale in('ar','he','en')),name text not null default '',short_description text not null default '',description text not null default '',seo_title text not null default '',seo_description text not null default '',included text not null default '',care text not null default '',primary key(product_id,locale));
create table public.product_collections(product_id text references public.products on delete cascade,collection_id text references public.collections on delete cascade,primary key(product_id,collection_id));
create table public.option_axes(id text primary key,product_id text not null references public.products on delete cascade,kind text not null check(kind in('metal_color','stone_size','shape','necklace_length','bracelet_length','ring_size','quantity_type','gemstone')),label jsonb not null,position integer not null default 0);
create table public.option_values(id text primary key,axis_id text not null references public.option_axes on delete cascade,label jsonb not null,numeric_value numeric,position integer not null default 0);
create table public.product_variants(id text primary key,product_id text not null references public.products on delete cascade,sku text unique not null,adjustment integer not null default 0,active boolean not null default true,stock integer check(stock>=0),gem jsonb not null default '{}',metal jsonb not null default '{}',measurements jsonb not null default '{}');
create table public.variant_options(variant_id text references public.product_variants on delete cascade,axis_id text references public.option_axes on delete cascade,value_id text not null references public.option_values on delete cascade,primary key(variant_id,axis_id));
create table public.media(id text primary key,src text not null,storage_path text unique,alt jsonb not null,kind text not null check(kind in('image','video','certificate')),width integer not null check(width>0),height integer not null check(height>0),mime text not null,bytes integer check(bytes>0),position integer not null default 0,created_at timestamptz not null default now());
create table public.product_media(product_id text references public.products on delete cascade,media_id text references public.media on delete restrict,position integer not null default 0,primary key(product_id,media_id));
create table public.variant_media(variant_id text references public.product_variants on delete cascade,media_id text references public.media on delete restrict,primary key(variant_id,media_id));
create table private.product_business(product_id text primary key references public.products on delete cascade,supplier_sku text not null default '',supplier_reference text not null default '',cost integer check(cost>=0),notes text not null default '');
create table public.shipping_zones(id text primary key,name jsonb not null,country text not null default 'IL',cities text[] not null default '{}',price integer not null check(price>=0),eta_min integer not null check(eta_min>=0),eta_max integer not null check(eta_max>=eta_min),active boolean not null default false);
create table public.store_settings(id boolean primary key default true check(id),config jsonb not null);
create table public.content_sections(id text primary key,kind text not null,enabled boolean not null default true,position integer not null,title jsonb not null,body jsonb not null,cta jsonb not null,href text not null,image text not null,selection text[] not null default '{}',layout text not null check(layout in('split','full','grid')));
create table public.content_pages(id text primary key,slug text unique not null,kind text not null check(kind in('policy','faq','education')),title jsonb not null,body jsonb not null,status text not null default 'draft' check(status in('draft','published')),legal_reviewed boolean not null default false,check(kind<>'policy' or status='draft' or legal_reviewed));
create table public.addresses(id text primary key,customer_id uuid not null references public.profiles on delete cascade,first_name text not null,last_name text not null,phone text not null,city text not null,street text not null,postal_code text not null default '',country text not null default 'IL');
create table private.discounts(id text primary key,code text unique not null,kind text not null check(kind in('fixed','percentage')),value integer not null check(value>0),active boolean not null default false,starts_at timestamptz,ends_at timestamptz,usage_limit integer check(usage_limit>0),used integer not null default 0 check(used>=0),minimum_subtotal integer not null default 0 check(minimum_subtotal>=0),product_ids text[] not null default '{}',collection_ids text[] not null default '{}',check(kind<>'percentage' or value<=100),check(ends_at is null or starts_at is null or ends_at>starts_at));
create table public.orders(id text primary key default gen_random_uuid()::text,number text unique not null default ('TH-'||upper(encode(gen_random_bytes(8),'hex'))),customer_id uuid references public.profiles on delete set null,locale text not null check(locale in('ar','he','en')),status text not null default 'payment_pending' check(status in('order_received','payment_pending','payment_confirmed','in_production','quality_check','ready_to_ship','shipped','delivered','cancelled','refunded')),payment_status text not null default 'pending' check(payment_status in('pending','paid','refunded')),payment_method text not null,subtotal integer not null check(subtotal>=0),discount integer not null check(discount>=0 and discount<=subtotal),shipping integer not null check(shipping>=0),total integer not null check(total=subtotal-discount+shipping),eta_min integer not null,eta_max integer not null,safe_tracking_url text check(safe_tracking_url is null or safe_tracking_url like 'https://%'),created_at timestamptz not null default now());
create table public.order_items(id text primary key default gen_random_uuid()::text,order_id text not null references public.orders,product_id text not null references public.products,variant_id text not null references public.product_variants,sku text not null,name jsonb not null,image text not null,options jsonb not null,gem jsonb not null,metal jsonb not null,measurements jsonb not null,quantity integer not null check(quantity between 1 and 10),unit_price integer not null check(unit_price>=0),line_total integer not null check(line_total=unit_price*quantity));
create table public.order_events(id text primary key default gen_random_uuid()::text,order_id text not null references public.orders,status text not null,at timestamptz not null default now());
create table private.order_contacts(order_id text primary key references public.orders,email_hash text not null,phone_hash text not null,customer jsonb not null,internal_notes text not null default '',supplier_reference text not null default '');
create table private.checkout_keys(key uuid primary key,request_hash text not null,order_id text unique references public.orders,created_at timestamptz not null default now());
create table private.discount_redemptions(discount_id text references private.discounts,order_id text unique references public.orders,amount integer not null,primary key(discount_id,order_id));
create table private.payment_events(provider text not null,event_id text not null,order_id text not null references public.orders,amount integer not null,currency text not null,outcome text not null,processed_at timestamptz not null default now(),primary key(provider,event_id));
create table public.reviews(id text primary key default gen_random_uuid()::text,product_id text not null references public.products,customer_id uuid references public.profiles,name text not null,rating integer check(rating between 1 and 5),text text not null default '',media text[] not null default '{}',verified boolean not null default false,status text not null default 'pending' check(status in('pending','approved','rejected','hidden')),created_at timestamptz not null default now(),check(rating is not null or length(text)>0));
create table public.wishlists(customer_id uuid references public.profiles on delete cascade,product_id text references public.products on delete cascade,primary key(customer_id,product_id));
create table private.concierge_requests(id text primary key default gen_random_uuid()::text,product_id text references public.products,name text not null,email text not null,phone text not null default '',message text not null,locale text not null,status text not null default 'open' check(status in('open','contacted','quoted','converted','closed')),created_at timestamptz not null default now());
create table private.notification_outbox(id text primary key default gen_random_uuid()::text,event_id text not null references public.order_events,order_id text not null references public.orders,channel text not null check(channel in('email','whatsapp')),audience text not null check(audience in('owner','customer')),template_id text not null,locale text not null,status text not null default 'pending' check(status in('pending','sent','failed','disabled')),attempts integer not null default 0,provider_id text,sent_at timestamptz,error text,next_attempt_at timestamptz,locked_at timestamptz,first_attempt_at timestamptz,payload jsonb,uncertain boolean not null default false,unique(event_id,channel,audience));
create table private.notification_logs(id bigint generated always as identity primary key,notification_id text references private.notification_outbox,attempt integer not null,outcome text not null,provider_id text,error text,at timestamptz not null default now());
create table private.audit_log(id text primary key default gen_random_uuid()::text,actor text not null,action text not null,target text not null,summary text not null default '',at timestamptz not null default now());
create table private.rate_limits(key text primary key,window_start timestamptz not null default now(),hits integer not null default 1);
create table private.upload_tickets(path text primary key,actor uuid not null references public.profiles,mime text not null,bytes integer not null,confirmed boolean not null default false,created_at timestamptz not null default now());
create index products_catalog_idx on public.products(status,category_id,featured,publish_at);
create index product_translation_name_idx on public.product_translations(locale,name);
create index variants_product_idx on public.product_variants(product_id);
create index orders_customer_date_idx on public.orders(customer_id,created_at desc);
create index orders_workflow_idx on public.orders(status,payment_status,created_at desc);
create index order_items_order_idx on public.order_items(order_id);
create index order_events_order_idx on public.order_events(order_id,at);
create index outbox_pending_idx on private.notification_outbox(next_attempt_at) where status='pending';
create index reviews_product_status_idx on public.reviews(product_id,status);
commit;
